add_filter( 'woocommerce_package_rates', 'perfectpixel_rates_by_cart_amount', 30 );

function perfectpixel_rates_by_cart_amount( $rates ) {
	$tiers = array();
	foreach ( explode( '|', '{{tiered_rates}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && is_numeric( $parts[0] ) && '' !== $parts[1] ) {
			$tiers[ $parts[1] ] = (float) $parts[0];
		}
	}
	if ( ! $tiers || ! WC()->cart ) {
		return $rates;
	}
	$amount = (float) WC()->cart->get_displayed_subtotal();
	$chosen = '';
	foreach ( $tiers as $rate_id => $min ) {
		if ( $amount >= $min && isset( $rates[ $rate_id ] ) && ( '' === $chosen || $min >= $tiers[ $chosen ] ) ) {
			$chosen = $rate_id;
		}
	}
	if ( '' === $chosen ) {
		return $rates;
	}
	foreach ( array_keys( $tiers ) as $rate_id ) {
		if ( $rate_id !== $chosen ) {
			unset( $rates[ $rate_id ] );
		}
	}
	return $rates;
}
